past={"INC-101":"payment timeout 급증 — PG사 응답 지연, 타임아웃 3초→5초 임시 상향","INC-117":"db pool exhausted — 배치가 커넥션 독점","INC-130":"dispatch retry 증가 — 위치 서버 배포 직후, 롤백"}
alert="ERROR payment timeout order=<n> after <n>ms 3건/분, 오류율 6.98%"
w=lambda s:{x.lower() for x in s.replace('—',' ').replace(',',' ').split() if len(x)>2}
for k,v in sorted(past.items(),key=lambda kv:len(w(alert)&w(kv[1])),reverse=True): print(len(w(alert)&w(v)),k)
# 2 INC-101
# 0 INC-117
# 0 INC-130
